const cache=new Map();
export function parts(epoch,zone){let f=cache.get(zone);if(!f){f=new Intl.DateTimeFormat('en-CA-u-ca-iso8601-nu-latn',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});cache.set(zone,f);}let p={};for(let x of f.formatToParts(epoch))if(x.type!=='literal')p[x.type]=Number(x.value);return {year:p.year,month:p.month,day:p.day,hour:p.hour,minute:p.minute,second:p.second};}
export function parseLocal(date,time){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!/^\d{2}:\d{2}$/.test(time))throw Error('date');let [year,month,day]=date.split('-').map(Number),[hour,minute]=time.split(':').map(Number),epoch=Date.UTC(year,month-1,day,hour,minute);if(year<2000||year>2100||hour>23||minute>59||new Date(epoch).toISOString().slice(0,16)!==date+'T'+time)throw Error('date');return epoch;}
export function offsetAt(epoch,zone){let p=parts(epoch,zone);return (Date.UTC(p.year,p.month-1,p.day,p.hour,p.minute,p.second)-epoch)/60000;}
export function resolveLocal(date,time,zone){const base=parseLocal(date,time),offsets=new Set();for(let h=-36;h<=36;h+=3)offsets.add(offsetAt(base+h*3600000,zone));let values=[];for(let offset of offsets){let candidate=base-offset*60000,p=parts(candidate,zone),target=Date.UTC(p.year,p.month-1,p.day,p.hour,p.minute);if(target===base)values.push(candidate);}return [...new Set(values)].sort((a,b)=>a-b);}
export function offsetText(epoch,zone){let n=offsetAt(epoch,zone),sign=n<0?'-':'+',a=Math.abs(n);return 'UTC'+sign+String(Math.floor(a/60)).padStart(2,'0')+':'+String(Math.round(a%60)).padStart(2,'0');}
export function localISO(epoch,zone){let p=parts(epoch,zone);return `${p.year}-${String(p.month).padStart(2,'0')}-${String(p.day).padStart(2,'0')} ${String(p.hour).padStart(2,'0')}:${String(p.minute).padStart(2,'0')}`;}
export function workMinute(s){if(!/^\d{2}:\d{2}$/.test(s))throw Error('hours');let [h,m]=s.split(':').map(Number);if(h>23||m>59)throw Error('hours');return h*60+m;}
export function validatePeople(people){if(!Array.isArray(people)||!people.length||people.length>6)throw Error('people');for(let p of people){if(workMinute(p.start)>=workMinute(p.end))throw Error('hours');parts(Date.now(),p.zone);}return people;}
export function isWorking(epoch,duration,p,weekdaysOnly){let start=workMinute(p.start),end=workMinute(p.end);for(let m=0;m<duration;m++){let v=parts(epoch+m*60000,p.zone),minute=v.hour*60+v.minute,day=new Date(Date.UTC(v.year,v.month-1,v.day)).getUTCDay();if(minute<start||minute>=end||(weekdaysOnly&&(day===0||day===6)))return false;}return true;}
export function checkDuration(value){let n=Number(value);if(!Number.isInteger(n)||n<15||n>240)throw Error('duration');return n;}
export function overlaps(date,zone,duration,people,weekdaysOnly){parseLocal(date,'00:00');checkDuration(duration);validatePeople(people);let candidates=[];for(let minute=0;minute<1440;minute+=30){let time=String(Math.floor(minute/60)).padStart(2,'0')+':'+String(minute%60).padStart(2,'0');for(let epoch of resolveLocal(date,time,zone)){if(people.every(p=>isWorking(epoch,duration,p,weekdaysOnly)))candidates.push(epoch);}}return candidates.sort((a,b)=>a-b);}
export function ics(epoch,duration,title){const stamp=t=>new Date(t).toISOString().replace(/[-:]/g,'').replace('.000','');const text=String(title).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//NaNa Lab//Meeting Time//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:'+epoch+'-'+duration+'@meeting.nanalab.local','DTSTAMP:'+stamp(epoch),'DTSTART:'+stamp(epoch),'DTEND:'+stamp(epoch+duration*60000),'SUMMARY:'+text,'END:VEVENT','END:VCALENDAR',''].join('\r\n');}
